WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_analysis_word'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '词句阐释', 'kp-sl-analysis-word', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合分析：词句阐释"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结构：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "是什么 + 为什么 + 怎么办。这是综合分析的黄金三段论。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“请谈谈你对材料中‘X’这个词/这句话的理解”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题骨架"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【是什么】：直接解释该词句的字面意思或本质含义（在材料中找原话翻译）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【为什么】：展开分析这个词背后的原因、影响（好的意义/坏的危害）、现状特征。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【怎么办】：针对上述分析，提出简要的对策或结论（通常一句话带过）。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "只解释不分析：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多考生只用了一段话解释字面意思就没词了。综合分析题给的分数很高，如果你不展开写“为什么”和“怎么办”，即使你第一步的解释再完美，也只能拿到 1/3 的分数！"}]}]}]}$$ AS jsonb), NULL, '词句阐释的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "综合分析", "词句理解"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_analysis_word", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
